-- NeoChat v1 schema. All IDs are UUIDv4 generated by the server or the client.

CREATE TABLE meta (
    key   text PRIMARY KEY,
    value text NOT NULL
);

CREATE TABLE invites (
    code_hash  bytea PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT now(),
    used_at    timestamptz,
    used_by    uuid
);

CREATE TABLE users (
    id                   uuid PRIMARY KEY,
    username             text NOT NULL UNIQUE,
    password_hash        text NOT NULL,
    account_identity_key bytea NOT NULL,
    identity_epoch       bigint NOT NULL,
    roster_revision      bigint NOT NULL,
    roster_blob          bytea NOT NULL,
    roster_sig           bytea NOT NULL,
    recovery_hash        bytea NOT NULL,
    created_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE devices (
    id                uuid PRIMARY KEY,
    user_id           uuid NOT NULL REFERENCES users(id),
    name              text NOT NULL,
    platform          text NOT NULL,
    is_primary        boolean NOT NULL,
    registration_id   integer NOT NULL,
    identity_key      bytea NOT NULL,
    auth_key          bytea NOT NULL,
    signed_prekey_id  integer NOT NULL,
    signed_prekey     bytea NOT NULL,
    signed_prekey_sig bytea NOT NULL,
    kyber_prekey_id   integer NOT NULL,
    kyber_prekey      bytea NOT NULL,
    kyber_prekey_sig  bytea NOT NULL,
    event_head        bigint NOT NULL DEFAULT 0,
    created_at        timestamptz NOT NULL DEFAULT now(),
    last_seen_at      timestamptz NOT NULL DEFAULT now(),
    revoked_at        timestamptz
);
CREATE INDEX devices_user ON devices(user_id) WHERE revoked_at IS NULL;

-- kind: 0 = EC one-time prekey, 1 = Kyber one-time prekey.
CREATE TABLE one_time_prekeys (
    device_id  uuid NOT NULL REFERENCES devices(id),
    kind       smallint NOT NULL,
    key_id     integer NOT NULL,
    public_key bytea NOT NULL,
    signature  bytea,
    PRIMARY KEY (device_id, kind, key_id)
);

CREATE TABLE sessions (
    id              uuid PRIMARY KEY,
    device_id       uuid NOT NULL REFERENCES devices(id),
    family          uuid NOT NULL,
    access_hash     bytea NOT NULL UNIQUE,
    access_expires  timestamptz NOT NULL,
    refresh_hash    bytea NOT NULL UNIQUE,
    refresh_expires timestamptz NOT NULL,
    replaced_by     uuid,
    replaced_at     timestamptz,
    revoked_at      timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_device ON sessions(device_id);

-- Pending link: a new device proved the password and waits for primary approval.
CREATE TABLE device_links (
    id          uuid PRIMARY KEY,
    user_id     uuid NOT NULL REFERENCES users(id),
    secret_hash bytea NOT NULL,
    device      jsonb NOT NULL,
    expires_at  timestamptz NOT NULL,
    approved_at timestamptz,
    roster      jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE contacts (
    owner_id   uuid NOT NULL REFERENCES users(id),
    contact_id uuid NOT NULL REFERENCES users(id),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, contact_id)
);

CREATE TABLE conversations (
    id         uuid PRIMARY KEY,
    kind       text NOT NULL CHECK (kind IN ('direct', 'group')),
    owner_id   uuid REFERENCES users(id),
    revision   bigint NOT NULL,
    state_blob bytea,
    state_sig  bytea,
    -- Leave statements signed by leaving members since the last owner-signed state.
    leaves     jsonb NOT NULL DEFAULT '[]',
    seq        bigint NOT NULL DEFAULT 0,
    archived   boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE memberships (
    conversation_id uuid NOT NULL REFERENCES conversations(id),
    user_id         uuid NOT NULL REFERENCES users(id),
    joined_revision bigint NOT NULL,
    PRIMARY KEY (conversation_id, user_id)
);
CREATE INDEX memberships_user ON memberships(user_id);

CREATE TABLE direct_pairs (
    user_a          uuid NOT NULL,
    user_b          uuid NOT NULL,
    conversation_id uuid NOT NULL REFERENCES conversations(id),
    PRIMARY KEY (user_a, user_b),
    CHECK (user_a < user_b)
);

CREATE TABLE messages (
    id                uuid PRIMARY KEY,
    conversation_id   uuid NOT NULL REFERENCES conversations(id),
    sender_device_id  uuid NOT NULL REFERENCES devices(id),
    client_message_id uuid NOT NULL,
    fingerprint       bytea NOT NULL,
    conversation_seq  bigint NOT NULL,
    accepted_at       timestamptz NOT NULL,
    UNIQUE (sender_device_id, client_message_id)
);
CREATE INDEX messages_accepted ON messages(accepted_at);

CREATE TABLE envelopes (
    message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
    device_id  uuid NOT NULL REFERENCES devices(id),
    ciphertext bytea NOT NULL,
    PRIMARY KEY (message_id, device_id)
);

CREATE TABLE device_events (
    device_id  uuid NOT NULL REFERENCES devices(id),
    seq        bigint NOT NULL,
    event_id   uuid NOT NULL UNIQUE,
    kind       text NOT NULL,
    message_id uuid REFERENCES messages(id) ON DELETE CASCADE,
    payload    jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (device_id, seq)
);
CREATE INDEX device_events_created ON device_events(created_at);

CREATE TABLE attachments (
    id              uuid PRIMARY KEY,
    owner_device_id uuid NOT NULL REFERENCES devices(id),
    size            bigint NOT NULL,
    sha256          bytea NOT NULL,
    state           text NOT NULL CHECK (state IN ('reserved', 'ready', 'attached')),
    message_id      uuid REFERENCES messages(id) ON DELETE SET NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    expires_at      timestamptz NOT NULL
);
CREATE INDEX attachments_expires ON attachments(expires_at);

CREATE TABLE push_tokens (
    device_id   uuid PRIMARY KEY REFERENCES devices(id),
    provider    text NOT NULL CHECK (provider IN ('fcm', 'apns')),
    token       text NOT NULL,
    environment text NOT NULL DEFAULT '',
    updated_at  timestamptz NOT NULL DEFAULT now()
);
